import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import { CURRENT_USER_ID, CURRENT_USER_NAME } from "../data/mockData";
import CreateListModal from "./CreateListModal";
import { api } from "../utils/api";

function ShoppingListPage() {
  const [lists, setLists] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const [showArchived, setShowArchived] = useState(false);
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);

  useEffect(() => {
    loadLists();
  }, []);

  const loadLists = async () => {
    try {
      setLoading(true);
      const data = await api.getLists();
      setLists(data);
      setError(null);
    } catch (err) {
      setError("Ошибка загрузки списков.");
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleCreateList = async (newListName) => {
    try {
      setLoading(true);
      await api.createList(newListName);
      await loadLists();
      setIsCreateModalOpen(false);
    } catch (err) {
      alert("Ошибка: " + err.message);
      setLoading(false);
    }
  };

  const handleDeleteList = async (listId) => {
    if (window.confirm("Удалить этот список?")) {
      try {
        await api.deleteList(listId);
        setLists((prev) => prev.filter((l) => l.id !== listId)); // Обрати внимание: Mongo использует _id, но мы мапим это в id в api.js если нужно, или используем _id. 
        // Но твой бэкенд возвращает id как _id. Давай проверим api.js. 
        // Если api.js просто возвращает JSON из монго, там будет поле _id. 
        // Но для простоты давай пока оставим id, если не сработает удаление из UI, просто обновим страницу.
        await loadLists(); // Самый надежный способ - перезагрузить список
      } catch (err) {
        alert("Ошибка при удалении.");
      }
    }
  };

  const handleToggleArchive = async (listId) => {
    try {
      await api.toggleArchiveList(listId);
      loadLists();
    } catch (err) {
      alert("Ошибка изменения статуса.");
    }
  };

  if (loading && lists.length === 0) return <div className="loading-state">Загрузка...</div>;
  if (error) return <div className="error-state">{error} <button onClick={loadLists}>Повторить</button></div>;

  const visibleLists = lists.filter(
    (list) =>
      list.members.includes(CURRENT_USER_ID) &&
      list.archived === showArchived // Используем поле archived из БД
  );

  const getOwnerName = (list) => {
    // ИСПРАВЛЕНО: owner -> ownerId
    return list.ownerId === CURRENT_USER_ID ? CURRENT_USER_NAME : "Sarah";
  };

  return (
    <>
      <div className="header">
        <h1>🛒 Мои списки</h1>
        <button
          className="button-primary"
          onClick={() => setIsCreateModalOpen(true)}
          disabled={loading}
        >
          + Новый список
        </button>
      </div>

      <div className="tabs">
        <button
          className={`tab-button ${!showArchived ? "active" : ""}`}
          onClick={() => setShowArchived(false)}
        >
          Активные
        </button>
        <button
          className={`tab-button ${showArchived ? "active" : ""}`}
          onClick={() => setShowArchived(true)}
        >
          Архив
        </button>
      </div>

      <div className="content">
        <div className="tile-grid">
          {visibleLists.map((list) => {
            // ИСПРАВЛЕНО: owner -> ownerId. MongoDB возвращает _id, так что используем list._id || list.id
            const listId = list.id || list._id; 
            const isOwner = list.ownerId === CURRENT_USER_ID;
            
            return (
              <div key={listId} className="list-tile">
                <div className="list-tile-content">
                  <Link
                    to={`/list/${listId}`}
                    style={{ textDecoration: "none" }}
                  >
                    <h3>{list.name}</h3>
                  </Link>
                  <p>
                    Владелец: {getOwnerName(list)}
                    <br />
                    Участников: {list.members.length}
                  </p>
                </div>
                <div className="list-tile-actions">
                  {isOwner && (
                    <button
                      className="button-icon"
                      title={list.archived ? "Восстановить" : "Архивировать"}
                      onClick={() => handleToggleArchive(listId)}
                    >
                      {list.archived ? "🔄" : "🗄️"}
                    </button>
                  )}
                  {isOwner && (
                    <button
                      className="button-icon"
                      title="Удалить"
                      onClick={() => handleDeleteList(listId)}
                    >
                      🗑️
                    </button>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {isCreateModalOpen && (
        <CreateListModal
          onClose={() => setIsCreateModalOpen(false)}
          onCreate={handleCreateList}
        />
      )}
    </>
  );
}

export default ShoppingListPage;
